// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1 ether, 100 ether);

        // owner (this test contract, deployer) triggers the suicide
        c.sudicideAnyone();

        // After destruction, the address has no code, so a plain call with
        // value and empty data must SUCCEED. The mutant keeps the code and
        // has no receive/fallback, so the same call REVERTS.
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(ok, "destroyed contract should accept value-carrying plain calls");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;
    function setUp() public { c = new C(); owner = msg.sender; }
    function testFuzz_property(address actor) public {
        vm.assume(actor != owner);
        vm.assume(actor != address(0));
        bool ok;
        vm.prank(actor);
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }
        assertTrue(!ok, "non-owner must not be able to destroy the contract");
    }
}

contract InvMutTest {
    C private c;

    constructor(C _c) {
        c = _c;
    }

    function runTest() public {
        (bool ok, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));
        assert(!ok);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint x, uint amount) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        try c.sudicideDrink{value: amount}() { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // This test contract is not the deployer/owner of c, so the owner-guarded
        // function must always revert from here. The mutant drops the guard and
        // completes the call, destroying c.
        require(true);
        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint x) public payable {
        require(true);
        bool reverted;
        // boundary
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) {
        // The counterexample passes this very contract as _c, making this test
        // contract both the target and the owner of C, so sudicideAnyone succeeds.
        // Exclude that input: c must be a distinct contract (not deployed by us).
        require(address(_c) != address(this));
        c = _c;
    }
    function run(uint x) public payable {
        require(true);
        bool reverted;
        // boundary
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}
